 resetResponseCaches()
 return c.NoContent(http.StatusNoContent)
}
func resetPeerCaches() error {
 client:=&http.Client{Timeout:5*time.Second}
 for _,peer:=range strings.Split(os.Getenv("ISUCON13_CACHE_PEERS"),",") {
  if peer=="" {continue}
  req,err:=http.NewRequest("POST",peer+"/internal/cache/reset",nil);if err!=nil{return err}
  req.Header.Set("X-Cache-Key",string(secret))
  resp,err:=client.Do(req);if err!=nil{return err}
  resp.Body.Close()
  if resp.StatusCode!=http.StatusNoContent{return fmt.Errorf("cache reset on %s: %d",peer,resp.StatusCode)}
 }
 return nil
}
