func getIconHandler(c echo.Context) error {
	username := c.Param("username")
	iconResponses.RLock()
	icon, ok := iconResponses.items[username]
	iconResponses.RUnlock()
	if !ok || time.Now().After(icon.until) {
		var row struct {
			Image []byte `db:"image"`
			Hash  string `db:"hash"`
		}
		if err := dbConn.GetContext(c.Request().Context(), &row, `SELECT i.image,COALESCE(i.hash,'') AS hash FROM users u LEFT JOIN icons i ON i.user_id=u.id WHERE u.name=?`, username); err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				return echo.NewHTTPError(http.StatusNotFound, "user not found")
			}
			return err
		}
		if row.Hash == "" {
			row.Image, row.Hash = fallbackBytes, fallbackHash
		}
		icon = cachedIcon{image: row.Image, hash: row.Hash, until: time.Now().Add(750 * time.Millisecond)}
		iconResponses.Lock()
		iconResponses.items[username] = icon
		iconResponses.Unlock()
	}
	etag := `"` + icon.hash + `"`
	c.Response().Header().Set("ETag", etag)
	if c.Request().Header.Get("If-None-Match") == etag {
		return c.NoContent(http.StatusNotModified)
	}
	return c.Blob(http.StatusOK, "image/jpeg", icon.image)
}

func postIconHandler(c echo.Context) error {
	ctx := c.Request().Context()

	if err := verifyUserSession(c); err != nil {
		// echo.NewHTTPErrorが返っているのでそのまま出力
		return err
	}

	// error already checked
	sess, _ := session.Get(defaultSessionIDKey, c)
	// existence already checked
	userID := sess.Values[defaultUserIDKey].(int64)

	var req *PostIconRequest
	if err := json.NewDecoder(c.Request().Body).Decode(&req); err != nil {
		return echo.NewHTTPError(http.StatusBadRequest, "failed to decode the request body as json")
	}

	tx, err := dbConn.BeginTxx(ctx, nil)
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to begin transaction: "+err.Error())
	}
	defer tx.Rollback()

	if _, err := tx.ExecContext(ctx, "DELETE FROM icons WHERE user_id = ?", userID); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to delete old user icon: "+err.Error())
	}

	rs, err := tx.StmtContext(ctx, iconInsertStmt).ExecContext(ctx, userID, req.Image, fmt.Sprintf("%x", sha256.Sum256(req.Image)))
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to insert new user icon: "+err.Error())
	}

	iconID, err := rs.LastInsertId()
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get last inserted icon id: "+err.Error())
	}

	if err := tx.Commit(); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to commit: "+err.Error())
	}

	invalidateUser(userID)
	invalidateIcon(sess.Values[defaultUsernameKey].(string))

	return c.JSON(http.StatusCreated, &PostIconResponse{
		ID: iconID,
	})
}

